SELECT 
    DATE(asub.submitted_at) AS event_date,
    COUNT(*) AS event_count
FROM assessment_submission asub
WHERE asub.assignment_id = #{assignmentId}
AND asub.submitted_at IS NOT NULL

    AND asub.session_id = #{sessionId}

AND asub.submitted_at >= #{rangeStart}
AND asub.submitted_at < #{rangeEnd}
GROUP BY DATE(asub.submitted_at)
ORDER BY event_date ASC

SELECT 
    DATE(asub.override_at) AS event_date,
    COUNT(*) AS event_count
FROM assessment_submission asub
WHERE asub.assignment_id = #{assignmentId}
AND asub.override_at IS NOT NULL

    AND asub.session_id = #{sessionId}

AND asub.override_at >= #{rangeStart}
AND asub.override_at < #{rangeEnd}
GROUP BY DATE(asub.override_at)
ORDER BY event_date ASC

SELECT 
    DATE(asub.updated_at) AS event_date,
    COUNT(*) AS event_count
FROM assessment_submission asub
WHERE asub.assignment_id = #{assignmentId}
AND asub.status = 'REOPENED'
AND asub.updated_at IS NOT NULL

    AND asub.session_id = #{sessionId}

AND asub.updated_at >= #{rangeStart}
AND asub.updated_at < #{rangeEnd}
GROUP BY DATE(asub.updated_at)
ORDER BY event_date ASC

SELECT asub.examiner_id AS examiner_id, u.user_name AS examiner_name, u.email AS examiner_email, COUNT(DISTINCT asub.session_id) AS session_count, COUNT(*) AS submission_count, SUM(CASE WHEN asub.status = 'SUBMITTED' THEN 1 ELSE 0 END) AS submitted_count, SUM(CASE WHEN asub.status = 'SUBMITTED' AND asub.total_score IS NOT NULL THEN asub.total_score ELSE 0 END) AS submitted_score_sum, SUM(CASE WHEN asub.status = 'SUBMITTED' AND asub.total_score IS NOT NULL THEN 1 ELSE 0 END) AS submitted_score_count FROM assessment_submission AS asub LEFT JOIN sys_user u ON asub.examiner_id = u.user_id WHERE asub.assignment_id = #{assignmentId}
AND asub.status IN
#{status}
GROUP BY asub.examiner_id, u.user_name, u.email
HAVING COUNT(DISTINCT asub.session_id) >= #{minSessions}
ORDER BY u.user_name ASC

SELECT COUNT(DISTINCT asub.session_id)
FROM assessment_submission AS asub
WHERE asub.assignment_id = #{assignmentId}

    AND asub.status IN

        #{status}

SELECT * FROM assessment_submission
WHERE assignment_id = #{assignmentId}
AND session_id = #{sessionId}
AND subject_type = #{subjectType}
AND subject_id = #{subjectId}
AND examiner_id = #{examinerId}
LIMIT 1

