UPDATE assessment_submission 
SET status = 'REOPENED',
    admin_note = #{reason},
    updated_at = NOW()
WHERE id = #{submissionId}
AND examiner_id = #{examinerId}

mapper.select:
SELECT ss.session_id, ss.start_at, ss.end_at, ss.venue_id, v.room_name as venue_name, COUNT(DISTINCT CONCAT(asub.subject_type, '_', asub.subject_id)) as participant_count FROM slot_sessions ss JOIN assessment_submission asub ON ss.session_id = asub.session_id LEFT JOIN venue v ON ss.venue_id = v.id WHERE asub.assignment_id = #{assignmentId}
AND ( DATE_FORMAT(ss.start_at, '%Y-%m-%d') LIKE CONCAT('%', #{searchQuery}, '%') OR DATE_FORMAT(ss.start_at, '%H:%i') LIKE CONCAT('%', #{searchQuery}, '%') OR v.room_name LIKE CONCAT('%', #{searchQuery}, '%') )
GROUP BY ss.session_id, ss.start_at, ss.end_at, ss.venue_id, v.room_name ORDER BY ss.start_at
LIMIT #{limit}
OFFSET #{offset}
